INSERT INTO public.cms_pages VALUES ('privacy', 'Privacy Policy', 'We respect your privacy. This policy describes how BUTTERBYTE PRIVATE LIMITED collects, uses, and protects information you provide while using butterbytestore.com.', '2026-05-30 23:49:41.970645+00');
INSERT INTO public.cms_pages VALUES ('terms', 'Terms & Conditions', 'By using BUTTERBYTE STORE you agree to the following terms and conditions.', '2026-05-30 23:49:41.970645+00');
INSERT INTO public.cms_pages VALUES ('shipping', 'Shipping Policy', 'We ship across India. Standard delivery 5-7 business days. Free shipping on prepaid orders above Rs. 999.', '2026-05-30 23:49:41.970645+00');
INSERT INTO public.cms_pages VALUES ('refund', 'Refund & Cancellation Policy', '7-day easy returns on eligible items. Refunds processed within 5-7 business days of pickup.', '2026-05-30 23:49:41.970645+00');
INSERT INTO public.cms_pages VALUES ('faq', 'FAQ', 'Have questions? Email communication@butterbytestore.com or call +91 8302628498.', '2026-05-30 23:49:41.970645+00');
INSERT INTO public.cms_pages VALUES ('about', 'Our Story', 'BUTTERBYTE STORE is a Delhi-born fashion house where tradition meets contemporary elegance. We are passionate about every detail — from the richness of premium fabrics and the precision of every stitch to the way each silhouette drapes effortlessly. Inspired by India''''s timeless craftsmanship and modern fashion sensibilities, our collections are designed to make every moment feel special.

At Butterbyte Store, we believe fashion is more than clothing; it is a reflection of confidence, individuality, and style. Every piece is thoughtfully created to deliver exceptional quality, comfort, and sophistication, ensuring you look and feel your best wherever you go.

Crafted with passion. Designed for elegance. Made to be remembered.', '2026-05-30 23:49:41.970645+00');


